def _pool3d_lane_spec_body(
    in_ptr,
    out_ptr,
    stride_in_n,
    stride_in_c,
    stride_in_d,
    stride_in_h,
    stride_in_w,
    stride_out_n,
    stride_out_c,
    stride_out_d,
    stride_out_h,
    stride_out_w,
    TOTAL,
    block_id,
    SPEC: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Pool one block of BLOCK flat output elements (one lane per output)."""
    C: tl.constexpr = SPEC[0]
    D_in: tl.constexpr = SPEC[1]
    H_in: tl.constexpr = SPEC[2]
    W_in: tl.constexpr = SPEC[3]
    D_out: tl.constexpr = SPEC[4]
    H_out: tl.constexpr = SPEC[5]
    W_out: tl.constexpr = SPEC[6]
    MAX_D: tl.constexpr = SPEC[7]
    MAX_H: tl.constexpr = SPEC[8]
    MAX_W: tl.constexpr = SPEC[9]

    arange = tl.arange(0, BLOCK)
    offs = block_id * BLOCK + arange
    mask = offs < TOTAL

    # Unravel the flat output index -> (n, c, d_o, h_o, w_o). Every divisor is
    # a compile-time constant, so the div/mod chains strength-reduce to
    # multiplies instead of the scalar-code emulation of runtime divisors.
    w_o = offs % W_out
    idx = offs // W_out
    h_o = idx % H_out
    idx = idx // H_out
    d_o = idx % D_out
    idx = idx // D_out
    c = idx % C
    n = idx // C

    d0 = (d_o * D_in) // D_out
    d1 = ((d_o + 1) * D_in + D_out - 1) // D_out
    h0 = (h_o * H_in) // H_out
    h1 = ((h_o + 1) * H_in + H_out - 1) // H_out
    w0 = (w_o * W_in) // W_out
    w1 = ((w_o + 1) * W_in + W_out - 1) // W_out

    nd = d1 - d0
    nh = h1 - h0
    nw = w1 - w0
    denom = (nd * nh * nw).to(tl.float32)

    base = n * stride_in_n + c * stride_in_c

    acc = tl.zeros((BLOCK,), dtype=tl.float32)
    for di in range(MAX_D):
        dmask = mask & (di < nd)
        for hi in range(MAX_H):
            dhmask = dmask & (hi < nh)
            for wi in range(MAX_W):
                wmask = dhmask & (wi < nw)
                in_idx = (
                    base
                    + (d0 + di) * stride_in_d
                    + (h0 + hi) * stride_in_h
                    + (w0 + wi) * stride_in_w
                )
                val = tl.load(in_ptr + in_idx, mask=wmask, other=0.0)
                acc += val.to(tl.float32)

    out_idx = (
        n * stride_out_n
        + c * stride_out_c
        + d_o * stride_out_d
        + h_o * stride_out_h
        + w_o * stride_out_w
    )
    tl.store(out_ptr + out_idx, acc / denom, mask=mask)


