@triton.jit
def adaptive_avg_pool3d_row_kernel(
    in_ptr,
    out_ptr,
    total_rows,
    C: tl.constexpr,
    D_in: tl.constexpr,
    H_in: tl.constexpr,
    W_in: tl.constexpr,
    D_out: tl.constexpr,
    H_out: tl.constexpr,
    W_out: tl.constexpr,
    stride_in_n,
    stride_in_c,
    stride_in_d,
    stride_in_h,
    stride_in_w,
    stride_out_n,
    stride_out_c,
    stride_out_d,
    stride_out_h,
    stride_out_w,
    NUM_PROGS: tl.constexpr,
    BLOCK_W: tl.constexpr,
    W_BLK: tl.constexpr,
    D_CHUNK: tl.constexpr,
    H_CHUNK: tl.constexpr,
    ACC_DTYPE: tl.constexpr,
):
    """Persistently pool output rows (n, c, d_o, h_o), W_out lanes wide.

    The pooling box is staged through [D_CHUNK, H_CHUNK, W_BLK] affine 3D
    tiles: the column axis stays contiguous, so the tiles take the vector
    load fast path even where the lane kernel's per-lane gathers would not.
    """
    pid = tl.program_id(axis=0)
    for row in range(pid, total_rows, NUM_PROGS):
        h_o = row % H_out
        tmp = row // H_out
        d_o = tmp % D_out
        tmp = tmp // D_out
        c = tmp % C
        n = tmp // C
        d0 = (d_o * D_in) // D_out
        d1 = ((d_o + 1) * D_in + D_out - 1) // D_out
        h0 = (h_o * H_in) // H_out
        h1 = ((h_o + 1) * H_in + H_out - 1) // H_out
        dd = d1 - d0
        hh = h1 - h0
        base_in = n * stride_in_n + c * stride_in_c
        base_out = (
            n * stride_out_n
            + c * stride_out_c
            + d_o * stride_out_d
            + h_o * stride_out_h
        )
        for w_off in range(0, W_out, BLOCK_W):
            last = tl.minimum(w_off + BLOCK_W, W_out)
            lw0 = (w_off * W_in) // W_out
            lw1 = (last * W_in + W_out - 1) // W_out
            lw1 = tl.minimum(lw1, W_in)
            w_o = w_off + tl.arange(0, BLOCK_W)
            w0_l = (w_o * W_in) // W_out
            w1_l = ((w_o + 1) * W_in + W_out - 1) // W_out
            ww_l = w1_l - w0_l
            denom = tl.cast(dd * hh * ww_l, ACC_DTYPE)
            cols = lw0 + tl.arange(0, W_BLK)
            col_mask = cols < lw1
            win_mask = (
                (cols[None, :] >= w0_l[:, None])
                & (cols[None, :] < w1_l[:, None])
                & col_mask[None, :]
            )
            acc = tl.zeros([BLOCK_W], dtype=ACC_DTYPE)
            for di in range(d0, d1, D_CHUNK):
                d_rows = di + tl.arange(0, D_CHUNK)
                d_mask = d_rows < d1
                for hi in range(h0, h1, H_CHUNK):
                    h_rows = hi + tl.arange(0, H_CHUNK)
                    h_mask = h_rows < h1
                    ptrs = (
                        in_ptr
                        + base_in
                        + d_rows[:, None, None] * stride_in_d
                        + h_rows[None, :, None] * stride_in_h
                        + cols[None, None, :] * stride_in_w
                    )
                    tile = tl.load(
                        ptrs,
                        mask=d_mask[:, None, None]
                        & h_mask[None, :, None]
                        & col_mask[None, None, :],
                        other=0.0,
                    ).to(ACC_DTYPE)
                    part = tl.sum(tile, axis=0)
                    part = tl.sum(part, axis=0)
                    acc += tl.sum(tl.where(win_mask, part[None, :], 0.0), axis=1)
            out_vals = (acc / denom).to(out_ptr.dtype.element_ty)
            tl.store(
                out_ptr + base_out + w_o * stride_out_w,
                out_vals,
                mask=w_o < W_out,
            )


