def _tile_meta(k_d, k_h, k_w):
    """Pick (BO, BR, num_warps): BR covers the window volume, BO the remainder.

    A wide window therefore gets most of the tile and few rows, while a narrow
    window gets many rows, so one shape covers both the small-output and the
    large-output cases without a host-side branch.
    """
    br = min(triton.next_power_of_2(k_d * k_h * k_w), _TILE_ELEMS // 2)
    bo = min(_TILE_BO_CAP, max(1, _TILE_ELEMS // br))
    # A tile of only a few hundred elements is launch-bound: four warps beat
    # eight there, because the eighth warp has no work left to overlap.
    warps = _TILE_WARPS if bo * br > 1024 else 4
    return bo, br, warps


def _exact_window_bound(in_size, out_size):
    """Exact maximum window extent along one axis.

    The window for output j is [floor(j*I/O), ceil((j+1)*I/O)), whose width is
    floor((r_j + I + O - 1) / O) with r_j = (j*I) mod O. As j sweeps, r_j
    covers exactly the multiples of g = gcd(I, O) below O, so the maximum is
    reached at r = O - g:

        max_w = (O - g + I + O - 1) // O

    The conservative cdiv+1 form overcounts whenever the fractional bin edges
    never stack up (e.g. 64 -> 7 has width exactly 10, not 11), which directly
    inflates the lane kernel's unrolled trip count.
    """
    if in_size <= 0 or out_size <= 0:
        return 1
    g = math.gcd(in_size, out_size)
    return (out_size - g + in_size + out_size - 1) // out_size


def _column_span(W_in, W_out, block_w):
    """Upper bound on the input-column span of one BLOCK_W-wide output block.

    The span is ceil(bw*I/O) - floor(w0*I/O) <= cdiv(bw*I, O) + 1 for bw <= O
    consecutive windows, capped at the whole axis. Closed form so the host
    never loops over W_out.
    """
    bw = min(block_w, W_out)
    span = triton.cdiv(bw * W_in, W_out) + 1
    return min(W_in, span)


def _lane_config(total, window_vol, itemsize):
    """(BLOCK, num_warps) for the lane kernel, from the core-shape sweep."""
    is_32bit = itemsize >= 4
    if total < _LANE_SMALL_TOTAL:
        return 512, (4 if is_32bit else 2)
    if window_vol <= _LANE_NARROW_WINDOW:
        return 2048, 2
    if is_32bit:
        return 1024, 4
    return 2048, 4


def _max_offset(t):
    return sum((size - 1) * stride for size, stride in zip(t.shape, t.stride())) + 1


def _normalize_output_size_3d(output_size):
    if isinstance(output_size, torch.Size):
        output_size = tuple(output_size)
    if isinstance(output_size, (list, tuple)):
        if len(output_size) != 3:
            raise ValueError(
                "output_size for _adaptive_avg_pool3d must have 3 elements (D_out, H_out, W_out)"
            )
        return tuple(int(x) for x in output_size)
    raise TypeError("output_size must be a sequence of three integers")


def _prepare_5d_input(t):
    if t.dim() == 5:
        return t, False
    if t.dim() == 4:
        return t.unsqueeze(0), True  # add N=1
    raise ValueError(
        "input for _adaptive_avg_pool3d must be 4D (C,D,H,W) or 5D (N,C,D,H,W)"
    )


def _launch_adaptive_avg_pool3d_kernel(x, out):
    N, C, D_in, H_in, W_in = x.shape
    D_out, H_out, W_out = out.shape[-3], out.shape[-2], out.shape[-1]

    stride_in_n, stride_in_c, stride_in_d, stride_in_h, stride_in_w = x.stride()
    stride_out_n, stride_out_c, stride_out_d, stride_out_h, stride_out_w = out.stride()

    total = N * C * D_out * H_out * W_out
    if total == 0:
        return

    # Exact window extents: tight trip counts for the lane walk and tight
    # chunks for the row kernel's 3D tiles.
    max_d = _exact_window_bound(D_in, D_out)
    max_h = _exact_window_bound(H_in, H_out)
    max_w = _exact_window_bound(W_in, W_out)
    window_vol = max_d * max_h * max_w

    # Strided views can address past numel(), so the int32 guard uses the real
    # max offset of both tensors, not their element counts.
    fits_i32 = (
        _max_offset(x) < _INT32_OFFSET_LIMIT and _max_offset(out) < _INT32_OFFSET_LIMIT
    )

    with torch_device_fn.device(x.device):
        if not fits_i32:
            # Outside the int32 safe domain: the tiled kernel's 64-bit index
            # path (all-constexpr dims there too, so no emulated div/mod).
            bo, br, tile_warps = _tile_meta(max_d, max_h, max_w)
            num_blocks = triton.cdiv(total, bo)
            multi = num_blocks > _GRID_CAP
            grid = (min(num_blocks, _GRID_CAP),)
            adaptive_avg_pool3d_tile_kernel[grid](
                x,
                out,
                stride_in_n,
                stride_in_c,
                stride_in_d,
                stride_in_h,
                stride_in_w,
                stride_out_n,
                stride_out_c,
                stride_out_d,
                stride_out_h,
                stride_out_w,
                (
                    total,
                    C,
                    D_in,
                    H_in,
                    W_in,
                    D_out,
                    H_out,
                    W_out,
                    max_d,
                    max_h,
                    max_w,
                    bo,
                    br,
                ),
                USE_I64=True,
                MULTI=multi,
                num_warps=tile_warps,
            )
            return

        if window_vol <= _ROW_MIN_WINDOW_VOL:
            # Narrow window: one lane per output with constexpr dims, so the
            # div/mod chains strength-reduce away.
            block, warps = _lane_config(total, window_vol, x.element_size())
            spec = (C, D_in, H_in, W_in, D_out, H_out, W_out, max_d, max_h, max_w)
            num_blocks = triton.cdiv(total, block)
            multi = num_blocks > _GRID_CAP
            grid = (min(num_blocks, _GRID_CAP),)
            adaptive_avg_pool3d_lane_kernel[grid](
                x,
                out,
                stride_in_n,
                stride_in_c,
                stride_in_d,
                stride_in_h,
                stride_in_w,
                stride_out_n,
                stride_out_c,
                stride_out_d,
                stride_out_h,
                stride_out_w,
                total,
                SPEC=spec,
                BLOCK=block,
                MULTI=multi,
                num_warps=warps,
            )
        else:
            # Wide window over a small output: walk output rows persistently
            # and stage the pooling box through affine 3D tiles.
            total_rows = N * C * D_out * H_out
            block_w = min(triton.next_power_of_2(W_out), 64)
            w_blk = triton.next_power_of_2(_column_span(W_in, W_out, block_w))
            h_chunk = min(triton.next_power_of_2(max_h), max(1, _ROW_TILE_CAP // w_blk))
            d_chunk = min(
                triton.next_power_of_2(max_d),
                max(1, _ROW_TILE_CAP // (h_chunk * w_blk)),
            )
            num_progs = min(total_rows, _ROW_NUM_PROGS)
            adaptive_avg_pool3d_row_kernel[(num_progs,)](
                x,
                out,
                total_rows,
                C=C,
                D_in=D_in,
                H_in=H_in,
                W_in=W_in,
                D_out=D_out,
                H_out=H_out,
                W_out=W_out,
                stride_in_n=stride_in_n,
                stride_in_c=stride_in_c,
                stride_in_d=stride_in_d,
                stride_in_h=stride_in_h,
                stride_in_w=stride_in_w,
                stride_out_n=stride_out_n,
                stride_out_c=stride_out_c,
                stride_out_d=stride_out_d,
                stride_out_h=stride_out_h,
                stride_out_w=stride_out_w,
                NUM_PROGS=num_progs,
                BLOCK_W=block_w,
                W_BLK=w_blk,
                D_CHUNK=d_chunk,
                H_CHUNK=h_chunk,
                ACC_DTYPE=tl.float32,
                num_warps=1,
            )
    return


def _adaptive_avg_pool3d(input: torch.Tensor, output_size):
    logger.debug("GEMS_ENFLAME _ADAPTIVE_AVG_POOL3D")
    x5d, squeezed = _prepare_5d_input(input)
    D_out, H_out, W_out = _normalize_output_size_3d(output_size)

    N, C, D_in, H_in, W_in = x5d.shape
    out_shape_5d = (N, C, D_out, H_out, W_out)
    out5d = torch.empty(
        out_shape_5d, device=x5d.device, dtype=x5d.dtype, layout=x5d.layout
    )

    _launch_adaptive_avg_pool3d_kernel(x5d, out5d)

    if squeezed:
        return out5d.squeeze(0)
    return out5d


def _adaptive_avg_pool3d_out(input: torch.Tensor, output_size, out: torch.Tensor):
    logger.debug("GEMS_ENFLAME _ADAPTIVE_AVG_POOL3D_OUT")
    x5d, squeezed = _prepare_5d_input(input)
    D_out, H_out, W_out = _normalize_output_size_3d(output_size)

    # Prepare out to be 5D if needed
    if squeezed:
        if out.dim() == 4:
            out5d = out.unsqueeze(0)
        elif out.dim() == 5 and out.size(0) == 1:
            out5d = out
        else:
            raise ValueError("Provided 'out' must be 4D (C,D,H,W) when input is 4D")
    else:
        out5d = out
        if out5d.dim() != 5:
            raise ValueError("Provided 'out' must be 5D (N,C,D,H,W) when input is 5D")

    # Validate shape
    expected_shape = (x5d.size(0), x5d.size(1), D_out, H_out, W_out)
    if tuple(out5d.shape) != expected_shape:
        raise ValueError(
            f"out has incorrect shape. Expected {expected_shape}, got {tuple(out5d.shape)}"
        )

    if out5d.device != x5d.device or out5d.dtype != x5d.dtype:
        raise ValueError(
            "out must be on the same device and have the same dtype as input"
        )

    _launch_adaptive_avg_pool3d_kernel(x5d, out5d)

    return out
